import { test, expect } from '@playwright/test';

test.describe('Payment Flow - Save Card Details', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/payment');
  });

  test('should display save card option', async ({ page }) => {
    const saveCardCheckbox = page.getByLabel('Save my card details for future purchases');
    await expect(saveCardCheckbox).toBeVisible();
  });

  test('should save card details when checkbox is selected', async ({ page }) => {
    await page.fill('input[name="cardNumber"]', '4111111111111111');
    await page.fill('input[name="expiryDate"]', '12/25');
    await page.fill('input[name="cvv"]', '123');

    const saveCardCheckbox = page.getByLabel('Save my card details for future purchases');
    await saveCardCheckbox.check();

    await page.click('button[type="submit"]');

    const successMessage = page.getByText('Your card details have been saved successfully.');
    await expect(successMessage).toBeVisible();
  });
});
